            make_q("What is Context Recall in RAG evaluation?", ["The extent to which all necessary information required to answer the question was successfully retrieved in the context", "The speed of the vector index", "The memory size of the index", "The number of chunks retrieved"], 0, "Context recall evaluates whether the retriever brought back all relevant facts present in the ground-truth reference answer."),
